            repaired.append(cur)
    routes = repaired

    # Local search: relocate single customers to reduce route count/length, preserving capacity.
    def route_demand(rt):
        s = 0
        for c in rt:
            s += demand_of(c)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        total = d(depot, rt[0])
        for i in range(len(rt) - 1):
            total += d(rt[i], rt[i + 1])
        total += d(rt[-1], depot)
        return total

    def total_cost(rs):
        s = 0
        for rt in rs:
            s += route_cost(rt)
        return s

    changed = True
    guard = 0
    while changed and guard < 50:
        guard += 1
        changed = False

        # Remove empty routes
        routes = [rt for rt in routes if rt]

        # Try merge routes if capacity allows.
        merged = True
        while merged:
            merged = False
            best_pair = None
            best_saving = None
            n = len(routes)
            for i in range(n):
                for j in range(i + 1, n):
                    if route_demand(routes[i]) + route_demand(routes[j]) <= cap:
                        a = routes[i]
                        b = routes[j]
                        saving = route_cost(a) + route_cost(b) - route_cost(a + b)
                        if best_saving is None or saving > best_saving or (saving == best_saving and (i, j) < best_pair):
                            best_saving = saving
                            best_pair = (i, j)
            if best_pair is not None and best_saving is not None and best_saving >= 0:
                i, j = best_pair
                routes[i] = routes[i] + routes[j]
                del routes[j]
                merged = True
                changed = True

        # One-pass relocate improvement.
        best_move = None
        best_delta = 0
        n = len(routes)
        for i in range(n):
            ri = routes[i]
            load_i = route_demand(ri)
            for pos in range(len(ri)):
                c = ri[pos]
                dem = demand_of(c)
                for j in range(n):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_demand(rj) + dem > cap:
                        continue
                    for ins in range(len(rj) + 1):
                        new_ri = ri[:pos] + ri[pos + 1:]
                        new_rj = rj[:ins] + [c] + rj[ins:]
                        old = route_cost(ri) + route_cost(rj)
                        new = route_cost(new_ri) + route_cost(new_rj)
                        delta = old - new
                        if delta > best_delta or (delta == best_delta and best_move is not None and (i, pos, j, ins, c) < best_move):
                            best_delta = delta
                            best_move = (i, pos, j, ins, c)
        if best_move is not None and best_delta > 0:
            i, pos, j, ins, c = best_move
            ri = routes[i]
            rj = routes[j]
            ri2 = ri[:pos] + ri[pos + 1:]
            rj2 = rj[:ins] + [c] + rj[ins:]
            if ri2:
                routes[i] = ri2
            else:
                del routes[i]
                if j > i:
                    j -= 1
            routes[j] = rj2
            changed = True

    # Final cleanup: ensure all customers exactly once.
    seen = {}
    for rt in routes:
        for c in rt:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    dup_routes = []
    for rt in routes:
        nr = []
        for c in rt:
            if seen.get(c, 0) > 1:
                seen[c] -= 1
                continue
            nr.append(c)
        if nr:
            dup_routes.append(nr)
    routes = dup_routes

    for c in missing:
        placed = False
        dem = demand_of(c)
        best = None
        best_idx = None
        best_pos = None
        for i, rt in enumerate(routes):
            if route_demand(rt) + dem <= cap:
                for pos in range(len(rt) + 1):
                    new_rt = rt[:pos] + [c] + rt[pos:]
                    delta = route_cost(rt) - route_cost(new_rt)
                    score = (delta, -len(rt), -i, -pos)
                    if best is None or score > best:
                        best = score
                        best_idx = i
                        best_pos = pos
        if best_idx is not None:
            rt = routes[best_idx]
            routes[best_idx] = rt[:best_pos] + [c] + rt[best_pos:]
            placed = True
        if not placed:
            routes.append([c])

    # Sort routes and within route deterministically by a light 2-opt-like repair using nearest insertion order.
    for idx in range(len(routes)):
        rt = routes[idx]
        if len(rt) <= 2:
            continue
        # deterministic local reordering by cheapest insertion from current sequence
        ordered_rt = [rt[0]]
        remaining = rt[1:]
        while remaining:
            best = None
            best_k = None
            for k, c in enumerate(remaining):
                for pos in range(len(ordered_rt) + 1):
                    prevn = depot if pos == 0 else ordered_rt[pos - 1]
                    nextn = depot if pos == len(ordered_rt) else ordered_rt[pos]
                    inc = d(prevn, c) + d(c, nextn) - d(prevn, nextn)
                    score = (inc, c, pos)
                    if best is None or score < best:
                        best = score
                        best_k = k
                        best_pos = pos
            c = remaining.pop(best_k)
            ordered_rt = ordered_rt[:best_pos] + [c] + ordered_rt[best_pos:]
        routes[idx] = ordered_rt

    # Remove empties
    routes = [rt for rt in routes if rt]
    return routes
